(2, 1, 'Euphoric', '🎉', '#FFB547', 'Big, joyful, arms-in-the-air.', '0.900', '0.900', '0.820', '0.080', '0.150', '118.0', '150.0'),
(3, 1, 'Energetic', '⚡', '#FF8A4C', 'Fast, loud and physical.', '0.900', '0.650', '0.780', '0.050', '0.250', '118.0', '165.0'),
(4, 1, 'Motivational', '🔥', '#F28C28', 'Builds momentum and keeps you going.', '0.840', '0.720', '0.620', '0.100', '0.100', '110.0', '150.0'),
(5, 1, 'Confident', '😎', '#B28DFF', 'Swagger and a steady strut.', '0.740', '0.600', '0.820', '0.100', '0.050', '85.0', '125.0'),
(6, 1, 'Adventurous', '🧭', '#3FB8AF', 'Wide-open and forward-moving.', '0.720', '0.600', '0.400', '0.250', '0.650', '100.0', '145.0'),
(7, 2, 'Romantic', '❤️', '#E86A92', 'Tender and close.', '0.400', '0.620', '0.550', '0.650', '0.050', '70.0', '110.0'),
(8, 2, 'Calm', '🧘', '#7CC6B5', 'Soft edges, steady pulse.', '0.250', '0.550', '0.300', '0.700', '0.500', '60.0', '100.0'),
(9, 2, 'Peaceful', '🕊️', '#A7C7E7', 'Still and spacious, close to silence.', '0.150', '0.520', '0.150', '0.850', '0.800', '50.0', '90.0'),
(10, 2, 'Relaxed', '🌿', '#8FBF7F', 'Easy grooves with nowhere to be.', '0.380', '0.650', '0.550', '0.550', '0.450', '70.0', '105.0'),
(11, 2, 'Focused', '🎯', '#5B8DEF', 'Steady and mostly wordless.', '0.300', '0.500', '0.350', '0.600', '0.880', '60.0', '110.0'),
(12, 2, 'Dreamy', '🌙', '#9D8CFF', 'Hazy, floating, late-night.', '0.450', '0.480', '0.520', '0.300', '0.550', '75.0', '115.0'),
(13, 4, 'Nostalgic', '💭', '#C9A27E', 'Warm, faded, a little bittersweet.', '0.480', '0.450', '0.500', '0.500', '0.150', '80.0', '120.0'),
(14, 4, 'Sad', '😔', '#6C8EBF', 'Slow and heavy-hearted.', '0.280', '0.180', '0.300', '0.720', '0.100', '60.0', '100.0'),
(15, 4, 'Melancholic', '🌧️', '#7A7FA8', 'Quietly sad, reflective.', '0.320', '0.280', '0.300', '0.600', '0.250', '60.0', '100.0'),
(16, 4, 'Emotional', '🥹', '#C77D9B', 'Big feelings, swelling strings and voice.', '0.480', '0.320', '0.350', '0.580', '0.100', '65.0', '110.0'),
(17, 3, 'Angry', '😤', '#D9534F', 'Loud release for frustration.', '0.900', '0.220', '0.450', '0.050', '0.100', '120.0', '180.0');

